using RealmForge.Domain.Entities;
using RealmForge.Shared.Characters;
using RealmForge.Shared.Enums;
using static RealmForge.Infrastructure.Persistence.Seeding.MagicItemSeeder;

namespace RealmForge.Infrastructure.Persistence.Seeding.MagicItemsData;

///	<summary>
///	Axe of the Dwarvish Lords (2014 ruleset). Item of the 2014 Dungeon Master's Guide outside the SRD: name and texts written by RealmForge (Italian and English).
///	</summary>
public static class AxeOfTheDwarvishLords2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("axe-of-the-dwarvish-lords", null, 0, MagicItemType.Weapon, ItemRarity.Artifact, true, ContentSource.RealmForge,
			Magic(Effect(MagicEffectKind.AttackAndDamage, 3)),
			("Ascia dei signori dei nani", "Arma (ascia da battaglia), artefatto (richiede sintonia)",
			"Un giovane principe nanico, convinto che il suo popolo avesse bisogno di un simbolo che lo unisse, scese più in profondità di qualsiasi altro nano fino al cuore ardente di un grande vulcano. Con l'aiuto di Moradin, il dio nanico della creazione, forgiò quattro grandi attrezzi (il Piccone Brutale, la Forgia del Focolare della Terra, l'Incudine del Canto e il Martello Plasmatore) e con essi l'Ascia dei signori nanici. Con l'artefatto riportò la pace tra i clan e fu ricordato come il Primo Re; l'ascia passò di erede in erede finché non andò perduta in una sanguinosa guerra civile. Ancora oggi i nani la cercano.\n\n***Arma magica.*** L'ascia concede un bonus di +3 ai tiri per colpire e ai danni effettuati con essa, e funziona anche come una *cintura nanica*, un *martello nanico da lancio* e una *spada affilata*.\n\n***Proprietà casuali.*** 2 proprietà benefiche minori, 1 proprietà benefica maggiore e 2 proprietà dannose minori.\n\n***Benedizioni di Moradin.*** Se il personaggio è un nano in sintonia con l'ascia, è immune ai danni da veleno, la gittata della sua scurovisione aumenta di 18 metri e ottiene competenza negli strumenti da artigiano legati alla lavorazione del metallo, alla birra e alla lavorazione della pietra.\n\n***Evocare un elementale della terra.*** Impugnando l'ascia, il personaggio può usare la sua azione per lanciare con essa *evoca elementale*, evocando un elementale della terra. Non può riusare questa proprietà fino all'alba successiva.\n\n***Viaggiare nelle profondità.*** Con un'azione, il personaggio può toccare con l'ascia un'opera muraria nanica fissa e lanciare *teletrasporto*. Se la destinazione è sotterranea non c'è alcuna probabilità di incidenti o di arrivi imprevisti. Non può riusare questa proprietà finché non sono passati 3 giorni.\n\n***Maledizione.*** L'ascia maledice qualsiasi non nano che entri in sintonia con essa, anche dopo la fine della sintonia: giorno dopo giorno l'aspetto e la statura della creatura diventano sempre più simili a quelli di un nano, finché dopo sette giorni sembra un nano qualsiasi, senza perdere i suoi tratti razziali né ottenere quelli dei nani. Il cambiamento non è magico (non può essere dissolto), ma può essere annullato da qualsiasi effetto che rimuova una maledizione, come *ristorare superiore* o *rimuovi maledizione*.\n\n***Distruggere l'ascia.*** L'unico modo è fonderla nella Forgia del Focolare della Terra, dove fu creata, lasciandola nel fuoco per cinquant'anni.", null),
			("Axe of the Dwarvish Lords", "Weapon (battleaxe), artifact (requires attunement)",
			"A young dwarf prince, convinced his people needed a symbol to unite them, went deeper than any dwarf before him, down to the blazing heart of a great volcano. With the help of Moradin, the dwarven god of creation, he forged four great tools (the Brutal Pick, the Earthheart Forge, the Anvil of Songs and the Shaping Hammer) and with them the Axe of the Dwarvish Lords. With it he brought peace to the clans and was remembered as the First King; the axe passed from heir to heir until it was lost in a bloody civil war. The dwarves still search for it.\n\n***Magic Weapon.*** The axe grants a +3 bonus to attack and damage rolls made with it, and it also works as a *belt of dwarvenkind*, a *dwarven thrower* and a *sword of sharpness*.\n\n***Random Properties.*** 2 minor beneficial properties, 1 major beneficial property and 2 minor detrimental properties.\n\n***Blessings of Moradin.*** If you are a dwarf attuned to the axe, you are immune to poison damage, the range of your darkvision increases by 60 feet, and you gain proficiency with the artisan's tools related to blacksmithing, brewing and stonemasonry.\n\n***Conjure Earth Elemental.*** While holding the axe, you can use your action to cast *conjure elemental* from it, summoning an earth elemental. You can't use this property again until the next dawn.\n\n***Travel the Depths.*** As an action, you can touch the axe to a fixed piece of dwarven stonework and cast *teleport*. If your destination is underground, there is no chance of a mishap or of arriving somewhere unexpected. You can't use this property again until 3 days have passed.\n\n***Curse.*** The axe curses any non-dwarf that attunes to it, even after the attunement ends: day by day the creature's appearance and stature become more dwarflike, until after seven days it looks like a typical dwarf, without losing its own racial traits or gaining those of a dwarf. The change isn't magical (it can't be dispelled), but any effect that removes a curse, such as *greater restoration* or *remove curse*, undoes it.\n\n***Destroying the Axe.*** The only way is to melt it down in the Earthheart Forge, where it was made, leaving it in the fire for fifty years.", null));
	}
}
